# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">NEML SURESİ 19. AYET UYGULAMALARI VE DUA BİLİNCİ</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Hz. Süleyman\'ın (as) Şükür Duası</text>\n  <text x="180" y="96" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ</text>\n  <text x="180" y="118" text-anchor="middle" font-size="11" fill="#334155">1. Bana ve anne-babama verdiğin nimete şükretmemi</text>\n  <text x="180" y="144" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">وَأَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ</text>\n  <text x="180" y="166" text-anchor="middle" font-size="11" fill="#334155">2. Razı olacağın salih amel işlememi bana ilham et</text>\n  <text x="180" y="192" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">وَأَدْخِلْنِي بِرَحْمَتِكَ فِي عِبَادِكَ الصَّالِحِينَ</text>\n  <text x="180" y="214" text-anchor="middle" font-size="11" fill="#334155">3. Rahmetinle beni salih kullarının arasına kat</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Ayetteki Kelime ve Okunuş İncelikleri</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• تَبَسَّمَ ضَاحِكًا: Güler yüzle tebessüm etti</text>\n  <text x="520" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• أَوْزِعْنِي: Bana ilham et, beni muvaffak kıl</text>\n  <text x="520" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• وَالِدَيَّ: Anne ve babam (Vâlideyy)</text>\n  <text x="520" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• عَمَلًا صَالِحًا: Allah\'ın rızasına uygun iyi iş</text>\n  <text x="520" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• الصَّالِحِينَ: Salih (iyi ve dürüst) kullar</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" fill="#166534">Karınca Vadisi kıssasında tevazu ve şükür</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TECVİT KURALLARINA GİRİŞ: MED VE KASR KAVRAMLARI</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Med (الْمَدُّ) — Uzatarak Okuma</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Sözlük anlamı: Uzatmak, çekmek, çoğaltmak</text>\n  <text x="180" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Tecvit anlamı: Sesi med harfleriyle uzatmaktır</text>\n  <text x="180" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Med Harfleri (حُرُوفُ الْمَدِّ): 3 tanedir</text>\n  <text x="180" y="174" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">1. Elif (ا) · 2. Vav (و) · 3. Yâ (ي)</text>\n  <text x="180" y="200" text-anchor="middle" font-size="11" fill="#713f12">Kendisinden önceki harfin harekesiyle uyumlu</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11" fill="#713f12">ve harekesiz (sâkin) olduklarında harf-i med olurlar</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Kasr (الْقَصْرُ) — Uzatmadan Okuma</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Sözlük anlamı: Kısaltmak, hapsetmek</text>\n  <text x="520" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Tecvit anlamı: Harfi kendi tabii ölçüsünde</text>\n  <text x="520" y="142" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">veya 1 elif miktarında kısa okumaktır</text>\n  <text x="520" y="168" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Mushafta harfin altındaki (قصر) işareti:</text>\n  <text x="520" y="192" text-anchor="middle" font-size="11" fill="#475569">Oradaki uzatma harfinin okunmayacağını</text>\n  <text x="520" y="212" text-anchor="middle" font-size="11" fill="#475569">veya 1 eliften fazla çekilmeyeceğini gösterir</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MED HARFLERİNİN ŞARTLARI VE MEDD-İ TABİİ (DOĞAL UZATMA)</text>\n  <rect x="20" y="45" width="210" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#be123c">1. Med Harfi: Elif (ا)</text>\n  <text x="125" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">Şartı: Harekeli olmamalı,</text>\n  <text x="125" y="116" text-anchor="middle" font-size="11" fill="#881337">önceki harf ÜSTÜN olmalı</text>\n  <text x="125" y="148" text-anchor="middle" font-size="14" font-weight="bold" fill="#be123c">قَالَ · كَانَ · صَالِحًا</text>\n  <text x="125" y="176" text-anchor="middle" font-size="11" fill="#881337">Kāle · Kâne · Sâlihan</text>\n  <text x="125" y="206" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">Ölçü: 1 Elif Miktarı</text>\n  <text x="125" y="224" text-anchor="middle" font-size="10" fill="#881337">(Bir parmak kaldırıp indirme süresi)</text>\n\n  <rect x="245" y="45" width="210" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#0e7490">2. Med Harfi: Vav (و)</text>\n  <text x="350" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">Şartı: Sâkin (harekesiz) olmalı,</text>\n  <text x="350" y="116" text-anchor="middle" font-size="11" fill="#164e63">önceki harf ÖTRE olmalı</text>\n  <text x="350" y="148" text-anchor="middle" font-size="14" font-weight="bold" fill="#0e7490">يَقُولُ · نُوحِيهَا · تَكُونُ</text>\n  <text x="350" y="176" text-anchor="middle" font-size="11" fill="#164e63">Yekûlü · Nûhîhâ · Tekûnü</text>\n  <text x="350" y="206" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">Ölçü: 1 Elif Miktarı</text>\n  <text x="350" y="224" text-anchor="middle" font-size="10" fill="#164e63">(Sebeb-i med yoksa Medd-i Tabii)</text>\n\n  <rect x="470" y="45" width="210" height="195" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">3. Med Harfi: Yâ (ي)</text>\n  <text x="575" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Şartı: Sâkin (harekesiz) olmalı,</text>\n  <text x="575" y="116" text-anchor="middle" font-size="11" fill="#14532d">önceki harf ESRE olmalı</text>\n  <text x="575" y="148" text-anchor="middle" font-size="14" font-weight="bold" fill="#15803d">قِيلَ · أَوْزِعْنِي · الصَّالِحِينَ</text>\n  <text x="575" y="176" text-anchor="middle" font-size="11" fill="#14532d">Kîle · Evzi\'nî · Es-sâlihîne</text>\n  <text x="575" y="206" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Örnek Kelime: نُوحِيهَا</text>\n  <text x="575" y="224" text-anchor="middle" font-size="10" fill="#14532d">(Üç med harfini bir arada barındırır)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
